def set_api_key(api_key, **_extra):
    import json, os, datetime, hashlib, base64, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0470000" if __import__("os").path.isdir("./environment_mix/0470000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    # --- Usage/audit log (create if missing schema file not provided) ---
    usage_file = "figma_usage.json"
    usage = _load(usage_file)
    if not isinstance(usage, list):
        usage = []

    def _log(status, credential_id=None, error=None):
        latency_ms = int((time.time() - start) * 1000)
        row = {
            "id": f"fuse_{int(time.time()*1000)}_{len(usage)+1}",
            "endpoint": "set_api_key",
            "credential_id": credential_id,
            "status": status,
            "error": error,
            "latency_ms": latency_ms,
            "created_at": now,
        }
        usage.append(row)
        _save(usage_file, usage)

    # --- Validate input ---
    if not isinstance(api_key, str) or not api_key.strip():
        _log("error", error={"code": "VALIDATION_ERROR", "message": "api_key is required"})
        return _err("VALIDATION_ERROR", "api_key is required")
    api_key = api_key.strip()
    if len(api_key) < 8:
        _log("error", error={"code": "VALIDATION_ERROR", "message": "api_key appears invalid (too short)"})
        return _err("VALIDATION_ERROR", "api_key appears invalid (too short)")

    accounts = _load("figma_accounts.json")
    if not isinstance(accounts, list):
        accounts = []

    # Fingerprint and last4
    fp = hashlib.sha256(api_key.encode("utf-8")).hexdigest()
    last4 = api_key[-4:]
    if len(last4) != 4:
        _log("error", error={"code": "VALIDATION_ERROR", "message": "api_key must be at least 4 characters"})
        return _err("VALIDATION_ERROR", "api_key must be at least 4 characters")

    # Uniqueness: unique(token_fingerprint_sha256)
    for a in accounts:
        if isinstance(a, dict) and a.get("token_fingerprint_sha256") == fp:
            # If already active and matches, idempotent success.
            if a.get("status") == "active":
                _log("ok", credential_id=a.get("id"))
                return {
                    "configured": True,
                    "account": {
                        "id": a.get("id"),
                        "status": a.get("status"),
                        "token_last4": a.get("token_last4"),
                        "last_validated_at": a.get("last_validated_at"),
                    }
                }
            # If exists but not active, we can transition to active (invalid->active allowed; revoked cannot).
            if a.get("status") == "revoked":
                _log("error", credential_id=a.get("id"), error={"code": "INVALID_TRANSITION", "message": "Revoked token cannot be re-activated"})
                return _err("INVALID_TRANSITION", "Revoked token cannot be re-activated")
            # invalid -> active allowed
            # First revoke any existing active token
            for b in accounts:
                if isinstance(b, dict) and b.get("status") == "active" and b.get("id") != a.get("id"):
                    b["status"] = "revoked"
                    b["updated_at"] = now
            a["status"] = "active"
            a["token_last4"] = last4
            a["token_ciphertext"] = base64.b64encode(api_key.encode("utf-8")).decode("ascii")
            a["updated_at"] = now
            a["validation_error"] = None
            a["last_validated_at"] = now
            _save("figma_accounts.json", accounts)
            _log("ok", credential_id=a.get("id"))
            return {
                "configured": True,
                "account": {
                    "id": a.get("id"),
                    "status": a.get("status"),
                    "token_last4": a.get("token_last4"),
                    "last_validated_at": a.get("last_validated_at"),
                }
            }

    # Otherwise create a new row; revoke any existing active first (business rule)
    for b in accounts:
        if isinstance(b, dict) and b.get("status") == "active":
            b["status"] = "revoked"
            b["updated_at"] = now

    # "Encrypt" token (store non-plaintext ciphertext). Offline: base64 as placeholder ciphertext.
    token_ciphertext = base64.b64encode(api_key.encode("utf-8")).decode("ascii")

    # Create ID with convention
    new_id = f"fa_{int(time.time()*1000)}_{len(accounts)+1}"
    row = {
        "id": new_id,
        "token_ciphertext": token_ciphertext,
        "token_last4": last4,
        "token_fingerprint_sha256": fp,
        "status": "active",
        "last_validated_at": now,
        "validation_error": None,
        "created_at": now,
        "updated_at": now,
    }
    accounts.append(row)
    _save("figma_accounts.json", accounts)
    _log("ok", credential_id=new_id)
    return {
        "configured": True,
        "account": {
            "id": new_id,
            "status": "active",
            "token_last4": last4,
            "last_validated_at": now,
        }
    }

def check_api_key(**_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0470000" if __import__("os").path.isdir("./environment_mix/0470000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    usage_file = "figma_usage.json"
    usage = _load(usage_file)
    if not isinstance(usage, list):
        usage = []

    def _log(status, credential_id=None, error=None):
        latency_ms = int((time.time() - start) * 1000)
        usage.append({
            "id": f"fuse_{int(time.time()*1000)}_{len(usage)+1}",
            "endpoint": "check_api_key",
            "credential_id": credential_id,
            "status": status,
            "error": error,
            "latency_ms": latency_ms,
            "created_at": now,
        })
        _save(usage_file, usage)

    accounts = _load("figma_accounts.json")
    if not isinstance(accounts, list):
        accounts = []

    active = None
    for a in accounts:
        if isinstance(a, dict) and a.get("status") == "active" and a.get("token_ciphertext"):
            active = a
            break

    if not active:
        _log("ok", credential_id=None)
        return {"configured": False, "account": None}

    # Offline behavior: treat active as configured; do not attempt vendor call.
    _log("ok", credential_id=active.get("id"))
    return {
        "configured": True,
        "account": {
            "id": active.get("id"),
            "status": active.get("status"),
            "token_last4": active.get("token_last4"),
            "last_validated_at": active.get("last_validated_at"),
            "validation_error": active.get("validation_error"),
        }
    }

def get_file(fileKey, version=None, depth=None, branch_data=None, **_extra):
    import json, os, datetime, time, hashlib, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0470000" if __import__("os").path.isdir("./environment_mix/0470000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "get_file"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso_z():
        return _now_utc().replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt_any(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _ensure_logs():
        path = os.path.join(_DB, "figma_request_logs.json")
        if not os.path.exists(path):
            _save("figma_request_logs.json", [])
        logs = _load("figma_request_logs.json")
        return logs if isinstance(logs, list) else []

    def _quota_check_and_log(status, credential_id=None, error_code=None, error_message=None, meta=None):
        # enforce basic rolling rate limit + daily quota using request logs
        logs = _ensure_logs()
        now_dt = _now_utc()
        # Defaults (service-like)
        rpm_limit = 120
        rpd_limit = 5000
        # optional overrides
        lim = _load("figma_rate_limits.json")
        lim0 = None
        if isinstance(lim, dict):
            lim0 = lim
        elif isinstance(lim, list) and lim and isinstance(lim[0], dict):
            lim0 = lim[0]
        if lim0:
            if isinstance(lim0.get("requests_per_minute"), int) and lim0.get("requests_per_minute") > 0:
                rpm_limit = lim0["requests_per_minute"]
            if isinstance(lim0.get("requests_per_day"), int) and lim0.get("requests_per_day") > 0:
                rpd_limit = lim0["requests_per_day"]

        cutoff_min = now_dt - datetime.timedelta(minutes=1)
        cutoff_day = now_dt - datetime.timedelta(days=1)
        rpm = 0
        rpd = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            ts = _parse_dt_any(r.get("timestamp") or r.get("created_at"))
            if not ts:
                continue
            if ts >= cutoff_min:
                rpm += 1
            if ts >= cutoff_day:
                rpd += 1

        if status == "precheck":
            if rpm_limit is not None and rpm >= rpm_limit:
                # log rejected call
                logs.append({
                    "id": "frl_" + uuid.uuid4().hex,
                    "endpoint": endpoint,
                    "credential_id": credential_id,
                    "status": "error",
                    "error_code": "RATE_LIMIT",
                    "error_message": "Rate limit exceeded.",
                    "latency_ms": int((time.time() - _t0) * 1000),
                    "timestamp": _now_iso_z(),
                    "meta": meta or {},
                })
                _save("figma_request_logs.json", logs)
                return _err("RATE_LIMIT", "Rate limit exceeded.")
            if rpd_limit is not None and rpd >= rpd_limit:
                logs.append({
                    "id": "frl_" + uuid.uuid4().hex,
                    "endpoint": endpoint,
                    "credential_id": credential_id,
                    "status": "error",
                    "error_code": "QUOTA_EXCEEDED",
                    "error_message": "Daily quota exceeded.",
                    "latency_ms": int((time.time() - _t0) * 1000),
                    "timestamp": _now_iso_z(),
                    "meta": meta or {},
                })
                _save("figma_request_logs.json", logs)
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
            return None

        logs.append({
            "id": "frl_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now_iso_z(),
            "meta": meta or {},
        })
        _save("figma_request_logs.json", logs)
        return None

    # Resolve active account (ambient auth)
    accounts = _load("figma_accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    active = next((a for a in accounts if isinstance(a, dict) and a.get("status") == "active" and a.get("token_ciphertext")), None)
    pre = _quota_check_and_log("precheck", credential_id=(active or {}).get("id"))
    if pre:
        return pre
    if not active:
        _quota_check_and_log("error", credential_id=None, error_code="UNAUTHORIZED", error_message="No active Figma token is configured.")
        return _err("UNAUTHORIZED", "No active Figma token is configured.")

    # Validate inputs
    if not isinstance(fileKey, str) or not fileKey.strip():
        _quota_check_and_log("error", credential_id=active.get("id"), error_code="VALIDATION_ERROR", error_message="fileKey must be a non-empty string.")
        return _err("VALIDATION_ERROR", "fileKey must be a non-empty string.", field="fileKey")
    fileKey = fileKey.strip()

    if version is not None and (not isinstance(version, str) or not version.strip()):
        _quota_check_and_log("error", credential_id=active.get("id"), error_code="VALIDATION_ERROR", error_message="version must be a non-empty string when provided.")
        return _err("VALIDATION_ERROR", "version must be a non-empty string when provided.", field="version")

    if depth is not None:
        if isinstance(depth, bool) or not isinstance(depth, (int, float)):
            _quota_check_and_log("error", credential_id=active.get("id"), error_code="VALIDATION_ERROR", error_message="depth must be a number when provided.")
            return _err("VALIDATION_ERROR", "depth must be a number when provided.", field="depth")
        d = int(depth)
        if float(depth) != float(d):
            _quota_check_and_log("error", credential_id=active.get("id"), error_code="VALIDATION_ERROR", error_message="depth must be an integer in [1,4].")
            return _err("VALIDATION_ERROR", "depth must be an integer in [1,4].", field="depth")
        if d < 1 or d > 4:
            _quota_check_and_log("error", credential_id=active.get("id"), error_code="VALIDATION_ERROR", error_message="depth must be within [1,4].")
            return _err("VALIDATION_ERROR", "depth must be within [1,4].", field="depth")
        depth = d

    if branch_data is not None and not isinstance(branch_data, bool):
        _quota_check_and_log("error", credential_id=active.get("id"), error_code="VALIDATION_ERROR", error_message="branch_data must be a boolean when provided.")
        return _err("VALIDATION_ERROR", "branch_data must be a boolean when provided.", field="branch_data")
    branch_data = bool(branch_data) if branch_data is not None else False

    # Ensure file entity exists; if missing, create it (offline-friendly)
    entities = _load("figma_entities.json")
    if not isinstance(entities, list):
        entities = []
    now_iso = _now_iso_z()
    file_ent = next((e for e in entities if isinstance(e, dict) and e.get("entity_type") == "file" and e.get("figma_id") == fileKey), None)
    if file_ent and file_ent.get("status") == "deleted":
        _quota_check_and_log("error", credential_id=active.get("id"), error_code="NOT_FOUND", error_message="File is deleted.")
        return _err("NOT_FOUND", "File not found or is not accessible.", fileKey=fileKey)

    if not file_ent:
        new_id = "fig_ent_" + datetime.datetime.now(datetime.timezone.utc).strftime("%y%m%d%H%M%S") + "_" + uuid.uuid4().hex[:12]
        file_ent = {
            "id": new_id,
            "entity_type": "file",
            "figma_id": fileKey,
            "parent_entity_id": None,
            "name": None,
            "status": "active",
            "branch_data_included": None,
            "list_cursor": None,
            "list_page_size": None,
            "fetched_at": None,
            "raw": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        # uniqueness(entity_type, figma_id): ensure no conflict
        entities.append(file_ent)
        _save("figma_entities.json", entities)

    # Try to reuse fresh snapshot
    snaps = _load("figma_file_snapshots.json")
    if not isinstance(snaps, list):
        snaps = []

    def _snap_match(s):
        if not isinstance(s, dict):
            return False
        if s.get("file_key") != fileKey:
            return False
        if (s.get("version") or None) != (version or None):
            return False
        if (s.get("depth") if s.get("depth") is not None else None) != (depth if depth is not None else None):
            return False
        if bool(s.get("branch_data")) != bool(branch_data):
            return False
        if s.get("node_ids") is not None:
            return False
        return True

    reusable = next((s for s in snaps if _snap_match(s) and s.get("status") == "fresh"), None)
    if reusable:
        # update entity fetched_at marker for observability
        for i, e in enumerate(entities):
            if isinstance(e, dict) and e.get("id") == file_ent.get("id"):
                e["fetched_at"] = now_iso
                e["updated_at"] = now_iso
                entities[i] = e
                _save("figma_entities.json", entities)
                break
        _quota_check_and_log("ok", credential_id=active.get("id"), meta={"cache": "hit", "snapshot_id": reusable.get("id")})
        return {"data": {"file": reusable.get("payload"), "snapshot": reusable}}

    # Offline "fetch from vendor": create/update snapshot deterministically from cached info
    # (must not fail just because no vendor access)
    payload = {
        "fileKey": fileKey,
        "version": version,
        "depth": depth,
        "branch_data": branch_data,
        "source": "offline_cache_refresh",
        "fetched_at": now_iso,
        "document": (file_ent.get("raw") if isinstance(file_ent.get("raw"), dict) else {"id": fileKey, "name": file_ent.get("name")}),
    }

    # Compute node_ids hash key component (none here)
    uniq = "|".join([
        fileKey,
        version or "",
        str(depth if depth is not None else -1),
        "1" if branch_data else "0",
        "",
    ])
    uniq_hash = hashlib.sha256(uniq.encode("utf-8")).hexdigest()

    existing_idx = None
    for idx, s in enumerate(snaps):
        if not isinstance(s, dict):
            continue
        if _snap_match(s):
            existing_idx = idx
            break

    if existing_idx is None:
        snap_id = "fig_snap_" + datetime.datetime.now(datetime.timezone.utc).strftime("%y%m%d%H%M%S") + "_" + uuid.uuid4().hex[:12]
        snap = {
            "id": snap_id,
            "file_entity_id": file_ent.get("id"),
            "file_key": fileKey,
            "version": version,
            "depth": depth,
            "branch_data": bool(branch_data),
            "node_ids": None,
            "status": "fresh",
            "payload": payload,
            "fetched_at": now_iso,
            "expires_at": None,
            "created_at": now_iso,
            "updated_at": now_iso,
            "_cache_key_sha256": uniq_hash,
        }
        snaps.append(snap)
        _save("figma_file_snapshots.json", snaps)
        snap_row = snap
    else:
        snap_row = snaps[existing_idx]
        # lifecycle transition to fresh allowed from stale
        if snap_row.get("status") == "evicted":
            _quota_check_and_log("error", credential_id=active.get("id"), error_code="INVALID_TRANSITION", error_message="Cannot refresh an evicted snapshot.")
            return _err("INVALID_TRANSITION", "Cannot refresh an evicted snapshot; must create a new one.", snapshot_id=snap_row.get("id"))
        snap_row["file_entity_id"] = file_ent.get("id")
        snap_row["payload"] = payload
        snap_row["fetched_at"] = now_iso
        snap_row["status"] = "fresh"
        snap_row["updated_at"] = now_iso
        snap_row["_cache_key_sha256"] = uniq_hash
        snaps[existing_idx] = snap_row
        _save("figma_file_snapshots.json", snaps)

    # Update entity markers
    for i, e in enumerate(entities):
        if isinstance(e, dict) and e.get("id") == file_ent.get("id"):
            e["fetched_at"] = now_iso
            e["updated_at"] = now_iso
            entities[i] = e
            _save("figma_entities.json", entities)
            break

    _quota_check_and_log("ok", credential_id=active.get("id"), meta={"cache": "miss", "snapshot_id": snap_row.get("id")})
    return {"data": {"file": snap_row.get("payload"), "snapshot": snap_row}}

def get_file_nodes(fileKey, node_ids, depth=None, version=None, **_extra):
    import json, os, datetime, time, hashlib, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0470000" if __import__("os").path.isdir("./environment_mix/0470000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "get_file_nodes"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso_z():
        return _now_utc().replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt_any(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _ensure_logs():
        path = os.path.join(_DB, "figma_request_logs.json")
        if not os.path.exists(path):
            _save("figma_request_logs.json", [])
        logs = _load("figma_request_logs.json")
        return logs if isinstance(logs, list) else []

    def _rate_quota_precheck(credential_id=None):
        logs = _ensure_logs()
        now_dt = _now_utc()
        rpm_limit = 120
        rpd_limit = 5000
        lim = _load("figma_rate_limits.json")
        lim0 = None
        if isinstance(lim, dict):
            lim0 = lim
        elif isinstance(lim, list) and lim and isinstance(lim[0], dict):
            lim0 = lim[0]
        if lim0:
            if isinstance(lim0.get("requests_per_minute"), int) and lim0.get("requests_per_minute") > 0:
                rpm_limit = lim0["requests_per_minute"]
            if isinstance(lim0.get("requests_per_day"), int) and lim0.get("requests_per_day") > 0:
                rpd_limit = lim0["requests_per_day"]

        cutoff_min = now_dt - datetime.timedelta(minutes=1)
        cutoff_day = now_dt - datetime.timedelta(days=1)
        rpm = 0
        rpd = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            ts = _parse_dt_any(r.get("timestamp") or r.get("created_at"))
            if not ts:
                continue
            if ts >= cutoff_min:
                rpm += 1
            if ts >= cutoff_day:
                rpd += 1
        if rpm >= rpm_limit:
            logs.append({
                "id": "frl_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "credential_id": credential_id,
                "status": "error",
                "error_code": "RATE_LIMIT",
                "error_message": "Rate limit exceeded.",
                "latency_ms": int((time.time() - _t0) * 1000),
                "timestamp": _now_iso_z(),
                "meta": {},
            })
            _save("figma_request_logs.json", logs)
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if rpd >= rpd_limit:
            logs.append({
                "id": "frl_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "credential_id": credential_id,
                "status": "error",
                "error_code": "QUOTA_EXCEEDED",
                "error_message": "Daily quota exceeded.",
                "latency_ms": int((time.time() - _t0) * 1000),
                "timestamp": _now_iso_z(),
                "meta": {},
            })
            _save("figma_request_logs.json", logs)
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    def _log(status, credential_id=None, error_code=None, error_message=None, meta=None):
        logs = _ensure_logs()
        logs.append({
            "id": "frl_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now_iso_z(),
            "meta": meta or {},
        })
        _save("figma_request_logs.json", logs)

    accounts = _load("figma_accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    active = next((a for a in accounts if isinstance(a, dict) and a.get("status") == "active" and a.get("token_ciphertext")), None)

    pre = _rate_quota_precheck(credential_id=(active or {}).get("id"))
    if pre:
        return pre
    if not active:
        _log("error", None, "UNAUTHORIZED", "No active Figma API token is configured.")
        return _err("UNAUTHORIZED", "No active Figma API token is configured.")

    if not isinstance(fileKey, str) or not fileKey.strip():
        _log("error", active.get("id"), "VALIDATION_ERROR", "fileKey must be a non-empty string.")
        return _err("VALIDATION_ERROR", "fileKey must be a non-empty string.", field="fileKey")
    fileKey = fileKey.strip()

    if not isinstance(node_ids, list) or len(node_ids) == 0 or any((not isinstance(x, str) or not x.strip()) for x in node_ids):
        _log("error", active.get("id"), "VALIDATION_ERROR", "node_ids must be a non-empty array of non-empty strings.")
        return _err("VALIDATION_ERROR", "node_ids must be a non-empty array of non-empty strings.", field="node_ids")
    node_ids = [x.strip() for x in node_ids]

    if version is not None and (not isinstance(version, str) or not version.strip()):
        _log("error", active.get("id"), "VALIDATION_ERROR", "version must be a non-empty string when provided.")
        return _err("VALIDATION_ERROR", "version must be a non-empty string when provided.", field="version")

    if depth is not None:
        if isinstance(depth, bool) or not isinstance(depth, (int, float)):
            _log("error", active.get("id"), "VALIDATION_ERROR", "depth must be a number when provided.")
            return _err("VALIDATION_ERROR", "depth must be a number when provided.", field="depth")
        d = int(depth)
        if float(depth) != float(d) or d < 1 or d > 4:
            _log("error", active.get("id"), "VALIDATION_ERROR", "depth must be an integer in [1,4].")
            return _err("VALIDATION_ERROR", "depth must be an integer in [1,4].", field="depth")
        depth = d

    entities = _load("figma_entities.json")
    if not isinstance(entities, list):
        entities = []
    now_iso = _now_iso_z()
    file_ent = next((e for e in entities if isinstance(e, dict) and e.get("entity_type") == "file" and e.get("figma_id") == fileKey), None)
    if file_ent and file_ent.get("status") == "deleted":
        _log("error", active.get("id"), "NOT_FOUND", "File is deleted.")
        return _err("NOT_FOUND", "File not found or is not accessible.", fileKey=fileKey)
    if not file_ent:
        new_id = "fig_ent_" + datetime.datetime.now(datetime.timezone.utc).strftime("%y%m%d%H%M%S") + "_" + uuid.uuid4().hex[:12]
        file_ent = {
            "id": new_id,
            "entity_type": "file",
            "figma_id": fileKey,
            "parent_entity_id": None,
            "name": None,
            "status": "active",
            "branch_data_included": None,
            "list_cursor": None,
            "list_page_size": None,
            "fetched_at": None,
            "raw": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        entities.append(file_ent)
        _save("figma_entities.json", entities)

    snaps = _load("figma_file_snapshots.json")
    if not isinstance(snaps, list):
        snaps = []

    node_ids_key = ",".join(sorted(node_ids))
    node_ids_hash = hashlib.sha256(node_ids_key.encode("utf-8")).hexdigest()

    def _snap_match(s):
        if not isinstance(s, dict):
            return False
        if s.get("file_key") != fileKey:
            return False
        if (s.get("version") or None) != (version or None):
            return False
        if (s.get("depth") if s.get("depth") is not None else None) != (depth if depth is not None else None):
            return False
        if bool(s.get("branch_data")) is not False:
            # nodes endpoint doesn't carry branch_data in signature; treat as branch_data=false cache key
            return False
        nids = s.get("node_ids")
        if not isinstance(nids, list) or len(nids) == 0:
            return False
        if hashlib.sha256(",".join(sorted([str(x) for x in nids])).encode("utf-8")).hexdigest() != node_ids_hash:
            return False
        return True

    reusable = next((s for s in snaps if _snap_match(s) and s.get("status") == "fresh"), None)
    if reusable:
        # Update entity fetched markers
        for i, e in enumerate(entities):
            if isinstance(e, dict) and e.get("id") == file_ent.get("id"):
                e["fetched_at"] = now_iso
                e["updated_at"] = now_iso
                entities[i] = e
                _save("figma_entities.json", entities)
                break
        payload = reusable.get("payload") if isinstance(reusable.get("payload"), dict) else {}
        nodes_map = payload.get("nodes") if isinstance(payload, dict) else None
        if not isinstance(nodes_map, dict):
            # best-effort: construct nodes map for requested ids
            nodes_map = {nid: {"id": nid, "source": "offline_cache"} for nid in node_ids}
        _log("ok", active.get("id"), meta={"cache": "hit", "snapshot_id": reusable.get("id")})
        return {"data": {"nodes": nodes_map, "snapshot": reusable}}

    # Create/update snapshot offline with nodes payload
    nodes_payload = {nid: {"id": nid, "source": "offline_cache_refresh"} for nid in node_ids}
    payload = {
        "fileKey": fileKey,
        "version": version,
        "depth": depth,
        "nodes": nodes_payload,
        "source": "offline_cache_refresh",
        "fetched_at": now_iso,
    }

    uniq = "|".join([fileKey, version or "", str(depth if depth is not None else -1), "0", node_ids_hash])
    uniq_hash = hashlib.sha256(uniq.encode("utf-8")).hexdigest()

    existing_idx = None
    for idx, s in enumerate(snaps):
        if not isinstance(s, dict):
            continue
        if _snap_match(s):
            existing_idx = idx
            break

    if existing_idx is None:
        snap_id = "fig_snap_" + datetime.datetime.now(datetime.timezone.utc).strftime("%y%m%d%H%M%S") + "_" + uuid.uuid4().hex[:12]
        snap = {
            "id": snap_id,
            "file_entity_id": file_ent.get("id"),
            "file_key": fileKey,
            "version": version,
            "depth": depth,
            "branch_data": False,
            "node_ids": node_ids,
            "status": "fresh",
            "payload": payload,
            "fetched_at": now_iso,
            "expires_at": None,
            "created_at": now_iso,
            "updated_at": now_iso,
            "_cache_key_sha256": uniq_hash,
        }
        snaps.append(snap)
        _save("figma_file_snapshots.json", snaps)
        snap_row = snap
    else:
        snap_row = snaps[existing_idx]
        if snap_row.get("status") == "evicted":
            _log("error", active.get("id"), "INVALID_TRANSITION", "Cannot refresh an evicted snapshot.")
            return _err("INVALID_TRANSITION", "Cannot refresh an evicted snapshot; must create a new one.", snapshot_id=snap_row.get("id"))
        snap_row["file_entity_id"] = file_ent.get("id")
        snap_row["payload"] = payload
        snap_row["fetched_at"] = now_iso
        snap_row["status"] = "fresh"
        snap_row["node_ids"] = node_ids
        snap_row["updated_at"] = now_iso
        snap_row["_cache_key_sha256"] = uniq_hash
        snaps[existing_idx] = snap_row
        _save("figma_file_snapshots.json", snaps)

    for i, e in enumerate(entities):
        if isinstance(e, dict) and e.get("id") == file_ent.get("id"):
            e["fetched_at"] = now_iso
            e["updated_at"] = now_iso
            entities[i] = e
            _save("figma_entities.json", entities)
            break

    _log("ok", active.get("id"), meta={"cache": "miss", "snapshot_id": snap_row.get("id")})
    return {"data": {"nodes": nodes_payload, "snapshot": snap_row}}

def get_image(fileKey, ids, scale=None, format=None, svg_include_id=None, svg_simplify_stroke=None, use_absolute_bounds=None, **_extra):
    import json, os, datetime, time, uuid, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0470000" if __import__("os").path.isdir("./environment_mix/0470000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "get_image"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso_z():
        return _now_utc().replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt_any(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _ensure_logs():
        path = os.path.join(_DB, "figma_request_logs.json")
        if not os.path.exists(path):
            _save("figma_request_logs.json", [])
        logs = _load("figma_request_logs.json")
        return logs if isinstance(logs, list) else []

    def _precheck_and_log_error(code, msg, credential_id=None, meta=None):
        logs = _ensure_logs()
        logs.append({
            "id": "frl_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": "error",
            "error_code": code,
            "error_message": msg,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now_iso_z(),
            "meta": meta or {},
        })
        _save("figma_request_logs.json", logs)

    def _precheck_rate_quota(credential_id=None):
        logs = _ensure_logs()
        now_dt = _now_utc()
        rpm_limit = 120
        rpd_limit = 5000
        lim = _load("figma_rate_limits.json")
        lim0 = None
        if isinstance(lim, dict):
            lim0 = lim
        elif isinstance(lim, list) and lim and isinstance(lim[0], dict):
            lim0 = lim[0]
        if lim0:
            if isinstance(lim0.get("requests_per_minute"), int) and lim0.get("requests_per_minute") > 0:
                rpm_limit = lim0["requests_per_minute"]
            if isinstance(lim0.get("requests_per_day"), int) and lim0.get("requests_per_day") > 0:
                rpd_limit = lim0["requests_per_day"]

        cutoff_min = now_dt - datetime.timedelta(minutes=1)
        cutoff_day = now_dt - datetime.timedelta(days=1)
        rpm = 0
        rpd = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            ts = _parse_dt_any(r.get("timestamp") or r.get("created_at"))
            if not ts:
                continue
            if ts >= cutoff_min:
                rpm += 1
            if ts >= cutoff_day:
                rpd += 1
        if rpm >= rpm_limit:
            _precheck_and_log_error("RATE_LIMIT", "Rate limit exceeded.", credential_id)
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if rpd >= rpd_limit:
            _precheck_and_log_error("QUOTA_EXCEEDED", "Daily quota exceeded.", credential_id)
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    def _log_ok(credential_id=None, meta=None):
        logs = _ensure_logs()
        logs.append({
            "id": "frl_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": "ok",
            "error_code": None,
            "error_message": None,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now_iso_z(),
            "meta": meta or {},
        })
        _save("figma_request_logs.json", logs)

    accounts = _load("figma_accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    active = next((a for a in accounts if isinstance(a, dict) and a.get("status") == "active" and a.get("token_ciphertext")), None)

    pre = _precheck_rate_quota(credential_id=(active or {}).get("id"))
    if pre:
        return pre
    if not active:
        _precheck_and_log_error("UNAUTHORIZED", "No active Figma API token is configured.", None)
        return _err("UNAUTHORIZED", "No active Figma API token is configured.")

    if not isinstance(fileKey, str) or not fileKey.strip():
        _precheck_and_log_error("VALIDATION_ERROR", "fileKey must be a non-empty string.", active.get("id"))
        return _err("VALIDATION_ERROR", "fileKey must be a non-empty string.", field="fileKey")
    fileKey = fileKey.strip()

    if not isinstance(ids, list) or len(ids) == 0 or any((not isinstance(x, str) or not x.strip()) for x in ids):
        _precheck_and_log_error("VALIDATION_ERROR", "ids must be a non-empty array of non-empty strings.", active.get("id"))
        return _err("VALIDATION_ERROR", "ids must be a non-empty array of non-empty strings.", field="ids")
    ids = [x.strip() for x in ids]

    if scale is not None:
        if isinstance(scale, bool) or not isinstance(scale, (int, float)):
            _precheck_and_log_error("VALIDATION_ERROR", "scale must be a number.", active.get("id"))
            return _err("VALIDATION_ERROR", "scale must be a number.", field="scale")
        if scale < 0.01 or scale > 4:
            _precheck_and_log_error("VALIDATION_ERROR", "scale must be within [0.01, 4].", active.get("id"))
            return _err("VALIDATION_ERROR", "scale must be within [0.01, 4].", field="scale")

    if format is not None:
        if not isinstance(format, str) or format not in ("jpg", "png", "svg", "pdf"):
            _precheck_and_log_error("VALIDATION_ERROR", "format must be one of: jpg, png, svg, pdf.", active.get("id"))
            return _err("VALIDATION_ERROR", "format must be one of: jpg, png, svg, pdf.", field="format")

    for bname, bval in (("svg_include_id", svg_include_id), ("svg_simplify_stroke", svg_simplify_stroke), ("use_absolute_bounds", use_absolute_bounds)):
        if bval is not None and not isinstance(bval, bool):
            _precheck_and_log_error("VALIDATION_ERROR", f"{bname} must be a boolean when provided.", active.get("id"))
            return _err("VALIDATION_ERROR", f"{bname} must be a boolean when provided.", field=bname)

    entities = _load("figma_entities.json")
    if not isinstance(entities, list):
        entities = []
    now_iso = _now_iso_z()

    file_ent = next((e for e in entities if isinstance(e, dict) and e.get("entity_type") == "file" and e.get("figma_id") == fileKey), None)
    if file_ent and file_ent.get("status") == "deleted":
        _precheck_and_log_error("NOT_FOUND", "File not found or is not accessible.", active.get("id"), meta={"fileKey": fileKey})
        return _err("NOT_FOUND", "File not found or is not accessible.", fileKey=fileKey)
    if not file_ent:
        # create file entity to accept valid request offline
        new_id = "fig_ent_" + datetime.datetime.now(datetime.timezone.utc).strftime("%y%m%d%H%M%S") + "_" + uuid.uuid4().hex[:12]
        file_ent = {
            "id": new_id,
            "entity_type": "file",
            "figma_id": fileKey,
            "parent_entity_id": None,
            "name": None,
            "status": "active",
            "branch_data_included": None,
            "list_cursor": None,
            "list_page_size": None,
            "fetched_at": None,
            "raw": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        entities.append(file_ent)
        _save("figma_entities.json", entities)

    renders = _load("figma_renders.json")
    if not isinstance(renders, list):
        renders = []

    ids_hash = hashlib.sha256(",".join(sorted(ids)).encode("utf-8")).hexdigest()
    fmt = format or None
    sc = float(scale) if scale is not None else None
    sig = "|".join([
        fileKey,
        "node_image",
        fmt or "",
        str(sc if sc is not None else -1),
        "1" if svg_include_id else "0",
        "1" if svg_simplify_stroke else "0",
        "1" if use_absolute_bounds else "0",
        ids_hash,
    ])
    sig_hash = hashlib.sha256(sig.encode("utf-8")).hexdigest()

    now_dt = _now_utc()

    reusable = None
    for r in renders:
        if not isinstance(r, dict):
            continue
        if r.get("file_key") != fileKey:
            continue
        if r.get("render_type") != "node_image":
            continue
        if r.get("status") != "complete":
            continue
        if not isinstance(r.get("result"), dict):
            continue
        # match options
        if (r.get("format") or None) != fmt:
            continue
        rs = r.get("scale")
        if rs is None and sc is not None:
            continue
        if rs is not None and sc is None:
            continue
        if rs is not None and sc is not None:
            try:
                if float(rs) != float(sc):
                    continue
            except Exception:
                continue
        if bool(r.get("svg_include_id") or False) != bool(svg_include_id or False):
            continue
        if bool(r.get("svg_simplify_stroke") or False) != bool(svg_simplify_stroke or False):
            continue
        if bool(r.get("use_absolute_bounds") or False) != bool(use_absolute_bounds or False):
            continue
        if not isinstance(r.get("node_ids"), list) or len(r.get("node_ids")) == 0:
            continue
        if hashlib.sha256(",".join(sorted([str(x) for x in r.get("node_ids")])).encode("utf-8")).hexdigest() != ids_hash:
            continue
        exp = _parse_dt_any(r.get("expires_at"))
        if exp is not None and exp <= now_dt:
            continue
        reusable = r
        break

    if reusable:
        _log_ok(active.get("id"), meta={"cache": "hit", "render_id": reusable.get("id")})
        return {"data": {"images": reusable.get("result"), "render": reusable}}

    # Create new render request (queued->complete immediately offline with placeholder URLs)
    render_id = "fig_rnd_" + datetime.datetime.now(datetime.timezone.utc).strftime("%y%m%d%H%M%S") + "_" + uuid.uuid4().hex[:12]
    result = {nid: f"offline://figma/{fileKey}/{nid}.{(fmt or 'png')}" for nid in ids}
    row = {
        "id": render_id,
        "file_entity_id": file_ent.get("id"),
        "file_key": fileKey,
        "render_type": "node_image",
        "node_ids": ids,
        "scale": sc,
        "format": fmt,
        "svg_include_id": svg_include_id if svg_include_id is not None else False,
        "svg_simplify_stroke": svg_simplify_stroke if svg_simplify_stroke is not None else False,
        "use_absolute_bounds": use_absolute_bounds if use_absolute_bounds is not None else False,
        "status": "complete",
        "result": result,
        "error": None,
        "requested_at": now_iso,
        "completed_at": now_iso,
        "expires_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
        "_cache_key_sha256": sig_hash,
    }

    # uniqueness constraint: if an older non-complete row exists for same signature, we can update it (idempotent-ish)
    existing_idx = None
    for idx, r in enumerate(renders):
        if not isinstance(r, dict):
            continue
        # best-effort match with stored cache key if present
        if r.get("_cache_key_sha256") and r.get("_cache_key_sha256") == sig_hash:
            existing_idx = idx
            break
    if existing_idx is not None:
        prev = renders[existing_idx]
        # allow failed->queued->complete or queued->complete; do not transition expired
        if prev.get("status") == "expired":
            # create new instead (cannot transition expired per schema)
            renders.append(row)
        else:
            prev.update(row)
            prev["id"] = prev.get("id") or render_id
            prev["updated_at"] = now_iso
            renders[existing_idx] = prev
    else:
        renders.append(row)

    _save("figma_renders.json", renders)

    # update entity markers
    for i, e in enumerate(entities):
        if isinstance(e, dict) and e.get("id") == file_ent.get("id"):
            e["fetched_at"] = now_iso
            e["updated_at"] = now_iso
            entities[i] = e
            _save("figma_entities.json", entities)
            break

    _log_ok(active.get("id"), meta={"cache": "miss", "render_id": row.get("id")})
    return {"data": {"images": result, "render": row}}

