    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "post_comment"

    def _now_iso_z():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _ensure_logs():
        path = os.path.join(_DB, "figma_request_logs.json")
        if not os.path.exists(path):
            _save("figma_request_logs.json", [])
        logs = _load("figma_request_logs.json")
