            _log("error", active.get("id"), "VALIDATION_ERROR", "client_meta must be an object when provided.")
            return _err("VALIDATION_ERROR", "client_meta must be an object when provided.", field="client_meta")
        allowed = {"x", "y", "node_id", "node_offset"}
        for k in client_meta.keys():
            if k not in allowed:
                _log("error", active.get("id"), "VALIDATION_ERROR", f"client_meta contains unknown field: {k}")
                return _err("VALIDATION_ERROR", f"client_meta contains unknown field: {k}", field=f"client_meta.{k}")
