            _log("error", active.get("id"), "VALIDATION_ERROR", "client_meta.node_id must be a non-empty string when provided.")
            return _err("VALIDATION_ERROR", "client_meta.node_id must be a non-empty string when provided.", field="client_meta.node_id")
        if "node_offset" in client_meta and client_meta["node_offset"] is not None:
