                return _err("VALIDATION_ERROR", "client_meta.node_offset must be an object when provided.", field="client_meta.node_offset")
            for kk in no.keys():
                if kk not in ("x", "y"):
                    _log("error", active.get("id"), "VALIDATION_ERROR", f"client_meta.node_offset contains unknown field: {kk}")
                    return _err("VALIDATION_ERROR", f"client_meta.node_offset contains unknown field: {kk}", field=f"client_meta.node_offset.{kk}")
            if "x" in no and no["x"] is not None and not isinstance(no["x"], (int, float)):
                _log("error", active.get("id"), "VALIDATION_ERROR", "client_meta.node_offset.x must be a number.")
                return _err("VALIDATION_ERROR", "client_meta.node_offset.x must be a number.", field="client_meta.node_offset.x")
            if "y" in no and no["y"] is not None and not isinstance(no["y"], (int, float)):
                _log("error", active.get("id"), "VALIDATION_ERROR", "client_meta.node_offset.y must be a number.")
                return _err("VALIDATION_ERROR", "client_meta.node_offset.y must be a number.", field="client_meta.node_offset.y")

    entities = _load("figma_entities.json")
