        entities = []
    comments = _load("figma_comments.json")
    if not isinstance(comments, list):
        comments = []
    now_iso = _now_iso_z()

    # Offline-friendly: create file entity if missing
    file_ent = next((e for e in entities if isinstance(e, dict) and e.get("entity_type") == "file" and e.get("figma_id") == fileKey), None)
    if file_ent and file_ent.get("status") == "deleted":
        _log("error", active.get("id"), "NOT_FOUND", "File not found or is not accessible.")
        return _err("NOT_FOUND", "File not found or is not accessible.", fileKey=fileKey)
    if not file_ent:
        new_id = "fig_ent_" + datetime.datetime.now(datetime.timezone.utc).strftime("%y%m%d%H%M%S") + "_" + uuid.uuid4().hex[:12]
        file_ent = {
            "id": new_id,
            "entity_type": "file",
            "figma_id": fileKey,
            "parent_entity_id": None,
            "name": None,
            "status": "active",
            "branch_data_included": None,
            "list_cursor": None,
            "list_page_size": None,
            "fetched_at": None,
            "raw": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        entities.append(file_ent)
        _save("figma_entities.json", entities)

    # Create local comment record; offline we treat as "posted" immediately with a generated vendor id
    local_id = "fig_cmt_" + datetime.datetime.now(datetime.timezone.utc).strftime("%y%m%d%H%M%S") + "_" + uuid.uuid4().hex[:12]
    figma_comment_id = "fc_" + uuid.uuid4().hex  # placeholder vendor id

    # uniqueness(file_key, figma_comment_id): ensure not colliding
    while any(isinstance(c, dict) and c.get("file_key") == fileKey and c.get("figma_comment_id") == figma_comment_id for c in comments):
        figma_comment_id = "fc_" + uuid.uuid4().hex

    row = {
        "id": local_id,
        "file_entity_id": file_ent.get("id"),
        "file_key": fileKey,
        "figma_comment_id": figma_comment_id,
        "parent_figma_comment_id": parent_id,
        "message": message,
        "client_meta": client_meta,
        "status": "active",
        "posted_to_vendor_at": now_iso,
        "deleted_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    # constraint: parent_figma_comment_id != figma_comment_id
    if row["parent_figma_comment_id"] is not None and row["parent_figma_comment_id"] == row["figma_comment_id"]:
        _log("error", active.get("id"), "VALIDATION_ERROR", "parent comment_id must not equal created comment id.")
        return _err("VALIDATION_ERROR", "comment_id must not equal the created comment id.", field="comment_id")

    comments.append(row)
    _save("figma_comments.json", comments)

    # Update entity markers
    for i, e in enumerate(entities):
        if isinstance(e, dict) and e.get("id") == file_ent.get("id"):
            e["fetched_at"] = now_iso
            e["updated_at"] = now_iso
            entities[i] = e
            _save("figma_entities.json", entities)
