def delete_comment(fileKey, comment_id, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0470000" if __import__("os").path.isdir("./environment_mix/0470000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = datetime.datetime.now(datetime.timezone.utc)

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _isoz(dt):
        if not isinstance(dt, datetime.datetime):
            dt = _now()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _lat_ms():
        return int((datetime.datetime.now(datetime.timezone.utc) - _t0).total_seconds() * 1000)

    def _append_log(status, credential_id=None, error_code=None, error_message=None, meta=None):
        logs = _load("figma_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "frl_" + os.urandom(12).hex(),
            "endpoint": "delete_comment",
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": _lat_ms(),
            "timestamp": _isoz(_now()),
            "meta": meta or {}
        })
        _save("figma_request_logs.json", logs)

    # Auth: must find an active usable token somewhere in store (ambient auth)
    accounts = _load("figma_accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    active = next((a for a in accounts if isinstance(a, dict) and a.get("status") == "active" and a.get("token_ciphertext")), None)
    if not active:
        _append_log("error", None, "UNAUTHORIZED", "No active Figma token is configured.")
        return _err("UNAUTHORIZED", "No active Figma token is configured.")

    # Validate inputs
    if not isinstance(fileKey, str) or not fileKey.strip():
        _append_log("error", active.get("id"), "VALIDATION_ERROR", "fileKey must be a non-empty string.", meta={"field": "fileKey"})
        return _err("VALIDATION_ERROR", "fileKey must be a non-empty string.", field="fileKey")
    if not isinstance(comment_id, str) or not comment_id.strip():
        _append_log("error", active.get("id"), "VALIDATION_ERROR", "comment_id must be a non-empty string.", meta={"field": "comment_id"})
        return _err("VALIDATION_ERROR", "comment_id must be a non-empty string.", field="comment_id")

    fileKey = fileKey.strip()
    comment_id = comment_id.strip()

    comments = _load("figma_comments.json")
    if not isinstance(comments, list):
        comments = []

    # Find matching row by (file_key, figma_comment_id)
    row = next((c for c in comments if isinstance(c, dict) and c.get("file_key") == fileKey and c.get("figma_comment_id") == comment_id), None)

    # If missing, be permissive & idempotent: create a deleted tombstone record so repeated deletes succeed
    # (Real systems often treat delete as idempotent even if local cache missed the comment.)
    now = _now()
    if row is None:
        # Ensure file entity exists or create a minimal one for referential consistency
        entities = _load("figma_entities.json")
        if not isinstance(entities, list):
            entities = []
        file_ent = next((e for e in entities if isinstance(e, dict) and e.get("entity_type") == "file" and e.get("figma_id") == fileKey), None)
        if file_ent is None:
            # Create minimal file entity (does not imply vendor existence; it's a local cache container)
            ent_id = "fig_ent_" + os.urandom(10).hex()
            file_ent = {
                "id": ent_id,
                "entity_type": "file",
                "figma_id": fileKey,
                "parent_entity_id": None,
                "name": None,
                "status": "active",
                "branch_data_included": None,
                "list_cursor": None,
                "list_page_size": None,
                "fetched_at": None,
                "raw": None,
                "created_at": _isoz(now),
                "updated_at": _isoz(now),
            }
            entities.append(file_ent)
            _save("figma_entities.json", entities)

        new_id = "fig_cmt_" + os.urandom(10).hex()
        tombstone = {
            "id": new_id,
            "file_entity_id": file_ent["id"],
            "file_key": fileKey,
            "figma_comment_id": comment_id,
            "parent_figma_comment_id": None,
            "message": "(deleted)",
            "client_meta": None,
            "status": "deleted",
            "posted_to_vendor_at": None,
            "deleted_at": _isoz(now),
            "created_at": _isoz(now),
            "updated_at": _isoz(now),
        }
        comments.append(tombstone)
        _save("figma_comments.json", comments)
        _append_log("ok", active.get("id"), meta={"idempotent": True, "created_tombstone": True})
        return {"data": {"deleted": True, "fileKey": fileKey, "comment_id": comment_id, "comment": tombstone}}

    # Idempotent delete
    if row.get("status") == "deleted":
        _append_log("ok", active.get("id"), meta={"idempotent": True, "already_deleted": True})
        return {"data": {"deleted": True, "fileKey": fileKey, "comment_id": comment_id, "comment": row}}

    # Transition active -> deleted only
    if row.get("status") != "active":
        _append_log("error", active.get("id"), "INVALID_TRANSITION", "Only active comments can be deleted.", meta={"current_status": row.get("status")})
        return _err("INVALID_TRANSITION", "Only active comments can be deleted.", current_status=row.get("status"))

    row["status"] = "deleted"
    row["deleted_at"] = _isoz(now)
    row["updated_at"] = _isoz(now)
    _save("figma_comments.json", comments)

    _append_log("ok", active.get("id"))
    return {"data": {"deleted": True, "fileKey": fileKey, "comment_id": comment_id, "comment": row}}

