    # Cursor handling: treat opaque string; store it on container entity.
    team_ent["list_cursor"] = cursor
    team_ent["list_page_size"] = page_size
    team_ent["updated_at"] = now

    # "Fetch from vendor": offline deterministic generation based on team_id + cursor.
    # We return cached project entities if already present; otherwise create up to page_size.
    # Cursor is interpreted as an integer offset when it matches "o:<int>", else start 0.
    offset = 0
    if cursor:
        if cursor.startswith("o:"):
            try:
                offset = int(cursor[2:])
                if offset < 0:
                    raise ValueError
            except ValueError:
                _log("get_team_projects", "error", credential_id=active_acct.get("id"), error_code="VALIDATION_ERROR")
