    # Build a stable "total" for the team.
    h = int(hashlib.sha256(team_id.encode("utf-8")).hexdigest()[:4], 16)
    total = 20 + (h % 31)  # 20..50
    end = min(total, offset + page_size)

    projects = []
    for idx in range(offset, end):
        project_id = f"{team_id}:{idx+1}"
        proj_ent = next((e for e in entities if isinstance(e, dict) and e.get("entity_type") == "project" and e.get("figma_id") == project_id), None)
