                "parent_entity_id": team_ent["id"],
                "name": f"Project {idx+1}",
                "status": "active",
                "branch_data_included": None,
                "list_cursor": None,
                "list_page_size": None,
                "fetched_at": now,
                "raw": {"id": project_id, "name": f"Project {idx+1}", "team_id": team_id},
                "created_at": now,
                "updated_at": now,
            }
            entities.append(proj_ent)
        else:
            # enforce parent relationship
            proj_ent["parent_entity_id"] = team_ent["id"]
            proj_ent["status"] = proj_ent.get("status") or "active"
            proj_ent["fetched_at"] = now
            proj_ent["raw"] = proj_ent.get("raw") or {"id": project_id, "name": proj_ent.get("name"), "team_id": team_id}
            proj_ent["updated_at"] = now

        projects.append({"id": proj_ent["figma_id"], "name": proj_ent.get("name")})

    next_cursor = f"o:{end}" if end < total else None
    team_ent["list_cursor"] = next_cursor  # store returned cursor for subsequent paging
    team_ent["fetched_at"] = now

    _save("figma_entities.json", entities)
    _log("get_team_projects", "ok", credential_id=active_acct.get("id"), meta={"team_id": team_id, "count": len(projects), "next_cursor": next_cursor})

    return {
        "team_id": team_id,
        "projects": projects,
        "pagination": {
            "cursor": cursor,
            "next_cursor": next_cursor,
            "page_size": page_size,
            "total": total,
            "has_more": next_cursor is not None,
        },
    }

