                "fetched_at": now,
                "raw": vendor_payload,
                "created_at": now,
                "updated_at": now,
            }
            assets.append(row)
            existing = row
        else:
            # keep team scope current
            existing["team_entity_id"] = team_ent["id"]
            existing["name"] = name
            existing["status"] = existing.get("status") if existing.get("status") in ("active", "deprecated", "deleted") else "active"
            if existing["status"] == "deleted":
                # do not resurrect deleted assets without explicit rule; keep deleted
                pass
            else:
                existing["status"] = "active"
            existing["fetched_at"] = now
            existing["raw"] = vendor_payload
            existing["updated_at"] = now

        page_items.append({"key": existing["asset_key"], "name": existing.get("name"), "description": existing.get("description")})

    next_cursor = f"o:{end}" if end < total else None
    team_ent["list_cursor"] = next_cursor
    team_ent["fetched_at"] = now

    _save("figma_entities.json", entities)
    _save("figma_asset_catalog.json", assets)
    _log("get_team_components", "ok", credential_id=active_acct.get("id"), meta={"team_id": team_id, "count": len(page_items), "next_cursor": next_cursor})

    return {
        "team_id": team_id,
        "components": page_items,
        "pagination": {
            "cursor": cursor,
            "next_cursor": next_cursor,
            "page_size": page_size,
            "total": total,
            "has_more": next_cursor is not None,
        },
    }

def get_file_components(fileKey, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0470000" if __import__("os").path.isdir("./environment_mix/0470000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "get_file_components"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso_z():
        return _now_utc().replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt_any(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _ensure_logs():
        path = os.path.join(_DB, "figma_request_logs.json")
        if not os.path.exists(path):
            _save("figma_request_logs.json", [])
        logs = _load("figma_request_logs.json")
        return logs if isinstance(logs, list) else []

    def _log(status, credential_id=None, error_code=None, error_message=None, meta=None):
        logs = _ensure_logs()
        logs.append({
            "id": "frl_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now_iso_z(),
            "meta": meta or {},
        })
        _save("figma_request_logs.json", logs)

    # auth
    accounts = _load("figma_accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    active = next((a for a in accounts if isinstance(a, dict) and a.get("status") == "active" and a.get("token_ciphertext")), None)
    if not active:
        _log("error", None, "UNAUTHORIZED", "No active Figma API token is configured.")
        return _err("UNAUTHORIZED", "No active Figma API token is configured.")

    if not isinstance(fileKey, str) or not fileKey.strip():
        _log("error", active.get("id"), "VALIDATION_ERROR", "fileKey must be a non-empty string.")
        return _err("VALIDATION_ERROR", "fileKey must be a non-empty string.", field="fileKey")
    fileKey = fileKey.strip()

    entities = _load("figma_entities.json")
    if not isinstance(entities, list):
        entities = []
    assets = _load("figma_asset_catalog.json")
    if not isinstance(assets, list):
        assets = []

    file_ent = next((e for e in entities if isinstance(e, dict) and e.get("entity_type") == "file" and e.get("figma_id") == fileKey), None)
    if file_ent and file_ent.get("status") == "deleted":
        _log("error", active.get("id"), "NOT_FOUND", "File not found or is not accessible.")
        return _err("NOT_FOUND", "File not found or is not accessible.", fileKey=fileKey)
    if not file_ent:
        # return empty set rather than error (read with no matches)
        _log("ok", active.get("id"), meta={"count": 0, "note": "file entity not cached"})
        return {"data": {"components": []}, "meta": {"count": 0}}

    out = []
    for a in assets:
        if not isinstance(a, dict):
            continue
        if a.get("asset_type") not in ("component", "component_set"):
            continue
        if a.get("file_key") != fileKey:
            continue
        if a.get("file_entity_id") and a.get("file_entity_id") != file_ent.get("id"):
            # tolerate mismatches; but include if file_key matches
            pass
        if a.get("status") == "deleted":
            continue
        out.append(a)

    # sort by name/key for stability
    out.sort(key=lambda r: (str(r.get("name") or ""), str(r.get("asset_key") or ""), str(r.get("id") or "")))

    _log("ok", active.get("id"), meta={"count": len(out)})
    return {"data": {"components": out}, "meta": {"count": len(out)}}

def get_component(key, **_extra):
    import json, os, datetime, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0470000" if __import__("os").path.isdir("./environment_mix/0470000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = datetime.datetime.now(datetime.timezone.utc)

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _isoz(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _lat_ms():
        return int((datetime.datetime.now(datetime.timezone.utc) - _t0).total_seconds() * 1000)

    def _append_log(status, credential_id=None, error_code=None, error_message=None, meta=None):
        logs = _load("figma_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "frl_" + os.urandom(12).hex(),
                "endpoint": "get_component",
                "credential_id": credential_id,
                "status": status,
                "error_code": error_code,
                "error_message": error_message,
                "latency_ms": _lat_ms(),
                "timestamp": _isoz(_now()),
                "meta": meta or {},
            }
        )
        _save("figma_request_logs.json", logs)

    # Validate input
    if not isinstance(key, str) or not key.strip():
        _append_log("error", None, "VALIDATION_ERROR", "key must be a non-empty string.", meta={"field": "key"})
        return _err("VALIDATION_ERROR", "key must be a non-empty string.", field="key")
    key = key.strip()

    # Ambient auth: must find SOME active configured token that can serve the request.
    accounts = _load("figma_accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    active_accounts = [
        a for a in accounts
        if isinstance(a, dict) and a.get("status") == "active" and a.get("token_ciphertext")
    ]
    if not active_accounts:
        _append_log("error", None, "UNAUTHORIZED", "No active Figma API token is configured.")
        return _err("UNAUTHORIZED", "No active Figma API token is configured.")

    assets = _load("figma_asset_catalog.json")
    if not isinstance(assets, list):
        assets = []

    # Lookup: component rows may be "component" or "component_set" in many integrations.
    # The tool is get_component; accept either if key matches, preferring component.
    matches = [
        a for a in assets
        if isinstance(a, dict)
        and a.get("asset_key") == key
        and a.get("asset_type") in ("component", "component_set")
    ]

    # If not found by exact key, relax slightly: some stores keep compound keys; try suffix/prefix match.
    if not matches:
        def _norm(s):
            return s.strip() if isinstance(s, str) else ""
        nk = _norm(key)
        matches = [
            a for a in assets
            if isinstance(a, dict)
            and _norm(a.get("asset_key")) == nk
            and a.get("asset_type") in ("component", "component_set")
        ]

    # If still not found, there is no cached record; real service would attempt vendor fetch.
    # Offline store cannot fetch vendor; surface NOT_FOUND (visibility/does not exist) but do not
    # mistakenly blame auth context.
    if not matches:
        cred_id = active_accounts[0].get("id")
        _append_log("error", cred_id, "NOT_FOUND", "Component not found.", meta={"key": key})
        return _err("NOT_FOUND", "Component not found.", key=key)

    # Prefer non-deleted, and prefer 'component' over 'component_set'
    def _rank(row):
        status = row.get("status")
        st = 0 if status == "active" else 1 if status == "deprecated" else 2
        typ = 0 if row.get("asset_type") == "component" else 1
        fetched = row.get("fetched_at")
        return (st, typ, 0 if fetched else 1)

    matches.sort(key=_rank)
    asset = matches[0]

    # Choose a credential that can satisfy access prerequisites:
    # If a token row exists with 403 validation_error, it may not access some teams; try other active tokens.
    # Since we have no per-asset ACL mapping, we only avoid tokens that are obviously unusable.
    def _token_usable(acct):
        if not isinstance(acct, dict):
            return False
        if acct.get("status") != "active" or not acct.get("token_ciphertext"):
            return False
        ve = acct.get("validation_error") or ""
        # treat explicit invalid/unauthorized errors as unusable
        if "401" in ve or "token invalid" in ve.lower():
            return False
        return True

    credential = None
    for acct in active_accounts:
        if _token_usable(acct):
            credential = acct
            break
    if credential is None:
        _append_log("error", None, "UNAUTHORIZED", "No usable active Figma API token is configured.")
        return _err("UNAUTHORIZED", "No usable active Figma API token is configured.")

    # Return an envelope derived strictly from stored row (no fabrication).
    # Provide a vendor-like payload using cached raw if present.
    out = {
        "component": asset.get("raw") if isinstance(asset.get("raw"), dict) else {
            "key": asset.get("asset_key"),
            "name": asset.get("name"),
            "description": asset.get("description"),
            "node_id": asset.get("node_id"),
        },
        "cache": {
            "id": asset.get("id"),
            "asset_type": asset.get("asset_type"),
            "status": asset.get("status"),
            "team_entity_id": asset.get("team_entity_id"),
            "file_entity_id": asset.get("file_entity_id"),
            "file_key": asset.get("file_key"),
            "fetched_at": asset.get("fetched_at"),
            "created_at": asset.get("created_at"),
            "updated_at": asset.get("updated_at"),
        },
    }

    _append_log("ok", credential.get("id"), None, None, meta={"key": key, "asset_id": asset.get("id")})
    return out

def get_team_component_sets(team_id, page_size=None, cursor=None, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0470000" if __import__("os").path.isdir("./environment_mix/0470000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_log_store():
        os.makedirs(_DB, exist_ok=True)
        log_name = "figma_request_logs.json"
        log_path = os.path.join(_DB, log_name)
        if not os.path.exists(log_path):
            _save(log_name, [])
        return log_name

    def _log(endpoint, status, credential_id=None, error_code=None, error_message=None, meta=None, started=None):
        log_name = _ensure_log_store()
        logs = _load(log_name)
        now = datetime.datetime.utcnow()
        latency_ms = None
        if isinstance(started, datetime.datetime):
            latency_ms = int((now - started).total_seconds() * 1000)
        row = {
            "id": f"frl_{now.strftime('%Y%m%d%H%M%S')}_{len(logs)+1}",
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "meta": meta or {},
            "latency_ms": latency_ms,
            "timestamp": now.replace(microsecond=0).isoformat() + "Z",
        }
        logs.append(row)
        _save(log_name, logs)

    def _rate_limit_check(endpoint):
        log_name = _ensure_log_store()
        logs = _load(log_name)
        now = datetime.datetime.utcnow()
        window_s = 60
        limit = 120
        cutoff = now - datetime.timedelta(seconds=window_s)
        recent = 0
        for r in logs:
            if r.get("endpoint") != endpoint:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts and ts >= cutoff:
                recent += 1
        if recent >= limit:
            return _err("RATE_LIMIT", f"Rate limit exceeded for {endpoint}. Try again later.", limit=limit, window_seconds=window_s)
        return None

    started = datetime.datetime.utcnow()
    endpoint = "get_team_component_sets"

    rl = _rate_limit_check(endpoint)
    if rl:
        _log(endpoint, "error", error_code=rl["error"]["code"], error_message=rl["error"]["message"], started=started)
        return rl

    if not isinstance(team_id, str) or not team_id.strip():
        e = _err("VALIDATION_ERROR", "team_id is required and must be a non-empty string.")
        _log(endpoint, "error", error_code=e["error"]["code"], error_message=e["error"]["message"], started=started)
        return e
    team_id = team_id.strip()

    if page_size is not None:
        # Tool schema says number; business rules say integer in [1,1000]
        if not isinstance(page_size, int):
            e = _err("VALIDATION_ERROR", "page_size must be an integer in [1,1000] when provided.")
            _log(endpoint, "error", error_code=e["error"]["code"], error_message=e["error"]["message"], started=started)
            return e
        if page_size < 1 or page_size > 1000:
            e = _err("VALIDATION_ERROR", "page_size must be an integer in [1,1000] when provided.")
            _log(endpoint, "error", error_code=e["error"]["code"], error_message=e["error"]["message"], started=started)
            return e

    if cursor is not None and (not isinstance(cursor, str)):
        e = _err("VALIDATION_ERROR", "cursor must be a string when provided.")
        _log(endpoint, "error", error_code=e["error"]["code"], error_message=e["error"]["message"], started=started)
        return e

    accounts = _load("figma_accounts.json")
    active_acct = None
    for a in accounts:
        if a.get("status") == "active" and isinstance(a.get("token_ciphertext"), str) and a.get("token_ciphertext"):
            active_acct = a
            break
    if not active_acct:
        e = _err("UNAUTHORIZED", "No active Figma API token is configured.")
        _log(endpoint, "error", error_code=e["error"]["code"], error_message=e["error"]["message"], started=started)
        return e

    entities = _load("figma_entities.json")
    team_entity = None
    for ent in entities:
        if ent.get("entity_type") == "team" and ent.get("figma_id") == team_id:
            team_entity = ent
            break
    if not team_entity or team_entity.get("status") == "deleted":
        e = _err("NOT_FOUND", "Team not found or not visible to the configured token.", team_id=team_id)
        _log(endpoint, "error", credential_id=active_acct.get("id"), error_code=e["error"]["code"], error_message=e["error"]["message"], started=started)
        return e

    # Cursor validation for this local cached listing:
    # We treat cursor as an index string like "i:<offset>". If present and not parseable -> VALIDATION_ERROR.
    offset = 0
    if cursor is not None and cursor != "":
        if not cursor.startswith("i:"):
            e = _err("VALIDATION_ERROR", "cursor is invalid for this listing.")
            _log(endpoint, "error", credential_id=active_acct.get("id"), error_code=e["error"]["code"], error_message=e["error"]["message"], started=started)
            return e
        try:
            offset = int(cursor.split(":", 1)[1])
        except Exception:
            e = _err("VALIDATION_ERROR", "cursor is invalid for this listing.")
            _log(endpoint, "error", credential_id=active_acct.get("id"), error_code=e["error"]["code"], error_message=e["error"]["message"], started=started)
            return e
        if offset < 0:
            e = _err("VALIDATION_ERROR", "cursor is invalid for this listing.")
            _log(endpoint, "error", credential_id=active_acct.get("id"), error_code=e["error"]["code"], error_message=e["error"]["message"], started=started)
            return e

    ps = page_size if page_size is not None else 100

    assets = _load("figma_asset_catalog.json")
    rows = []
    for a in assets:
        if a.get("asset_type") != "component_set":
            continue
        if a.get("team_entity_id") != team_entity.get("id"):
            continue
        if a.get("status") == "deleted":
            continue
        rows.append(a)

    def _k(x):
        n = x.get("name")
        return ((n or "").lower(), x.get("asset_key") or "", x.get("id") or "")

    rows.sort(key=_k)

    total = len(rows)
    page = rows[offset: offset + ps]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = f"i:{next_offset}" if has_more else None

    # Store pagination hints on the team entity (business rule)
    team_entity["list_cursor"] = cursor
    team_entity["list_page_size"] = ps
    team_entity["updated_at"] = _now_iso()
    # Persist entity update
    for i, ent in enumerate(entities):
        if ent.get("id") == team_entity.get("id"):
            entities[i] = team_entity
            break
    _save("figma_entities.json", entities)

    resp = {
        "component_sets": page,
        "meta": {
            "team_id": team_id,
            "total": total,
            "page_size": ps,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "source": "cache",
        },
    }
    _log(endpoint, "ok", credential_id=active_acct.get("id"), meta={"team_id": team_id, "returned": len(page), "total": total}, started=started)
    return resp

