        e = _err("VALIDATION_ERROR", "cursor must be a string when provided.")
        _log(endpoint, "error", error_code=e["error"]["code"], error_message=e["error"]["message"], started=started)
        return e

    accounts = _load("figma_accounts.json")
    active_acct = None
    for a in accounts:
        if a.get("status") == "active" and isinstance(a.get("token_ciphertext"), str) and a.get("token_ciphertext"):
            active_acct = a
            break
    if not active_acct:
        e = _err("UNAUTHORIZED", "No active Figma API token is configured.")
        _log(endpoint, "error", error_code=e["error"]["code"], error_message=e["error"]["message"], started=started)
        return e

    entities = _load("figma_entities.json")
    team_entity = None
    for ent in entities:
        if ent.get("entity_type") == "team" and ent.get("figma_id") == team_id:
            team_entity = ent
            break
    if not team_entity or team_entity.get("status") == "deleted":
        e = _err("NOT_FOUND", "Team not found or not visible to the configured token.", team_id=team_id)
        _log(endpoint, "error", credential_id=active_acct.get("id"), error_code=e["error"]["code"], error_message=e["error"]["message"], started=started)
        return e

    offset = 0
    if cursor is not None and cursor != "":
        if not cursor.startswith("i:"):
            e = _err("VALIDATION_ERROR", "cursor is invalid for this listing.")
            _log(endpoint, "error", credential_id=active_acct.get("id"), error_code=e["error"]["code"], error_message=e["error"]["message"], started=started)
            return e
        try:
            offset = int(cursor.split(":", 1)[1])
        except Exception:
            e = _err("VALIDATION_ERROR", "cursor is invalid for this listing.")
            _log(endpoint, "error", credential_id=active_acct.get("id"), error_code=e["error"]["code"], error_message=e["error"]["message"], started=started)
            return e
        if offset < 0:
            e = _err("VALIDATION_ERROR", "cursor is invalid for this listing.")
            _log(endpoint, "error", credential_id=active_acct.get("id"), error_code=e["error"]["code"], error_message=e["error"]["message"], started=started)
            return e

    ps = page_size if page_size is not None else 100

    assets = _load("figma_asset_catalog.json")
    rows = []
    for a in assets:
        if a.get("asset_type") != "style":
            continue
        if a.get("team_entity_id") != team_entity.get("id"):
            continue
        if a.get("status") == "deleted":
            continue
        rows.append(a)

    def _k(x):
        n = x.get("name")
        return ((n or "").lower(), x.get("asset_key") or "", x.get("id") or "")

    rows.sort(key=_k)

    total = len(rows)
    page = rows[offset: offset + ps]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = f"i:{next_offset}" if has_more else None

    team_entity["list_cursor"] = cursor
    team_entity["list_page_size"] = ps
    team_entity["updated_at"] = _now_iso()
    for i, ent in enumerate(entities):
        if ent.get("id") == team_entity.get("id"):
            entities[i] = team_entity
            break
    _save("figma_entities.json", entities)

    resp = {
        "styles": page,
        "meta": {
            "team_id": team_id,
            "total": total,
            "page_size": ps,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "source": "cache",
        },
    }
    _log(endpoint, "ok", credential_id=active_acct.get("id"), meta={"team_id": team_id, "returned": len(page), "total": total}, started=started)
    return resp

