        logs.append({
            "id": "frl_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now_iso_z(),
            "meta": meta or {},
        })
        _save("figma_request_logs.json", logs)

    accounts = _load("figma_accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    active = next((a for a in accounts if isinstance(a, dict) and a.get("status") == "active" and a.get("token_ciphertext")), None)
    if not active:
        _log("error", None, "UNAUTHORIZED", "No active Figma API token is configured.")
        return _err("UNAUTHORIZED", "No active Figma API token is configured.")

    if not isinstance(fileKey, str) or not fileKey.strip():
        _log("error", active.get("id"), "VALIDATION_ERROR", "fileKey must be a non-empty string.")
        return _err("VALIDATION_ERROR", "fileKey must be a non-empty string.", field="fileKey")
    fileKey = fileKey.strip()

    entities = _load("figma_entities.json")
    if not isinstance(entities, list):
        entities = []
    assets = _load("figma_asset_catalog.json")
    if not isinstance(assets, list):
        assets = []

    file_ent = next((e for e in entities if isinstance(e, dict) and e.get("entity_type") == "file" and e.get("figma_id") == fileKey), None)
    if file_ent and file_ent.get("status") == "deleted":
        _log("error", active.get("id"), "NOT_FOUND", "File not found or is not accessible.")
        return _err("NOT_FOUND", "File not found or is not accessible.", fileKey=fileKey)
    if not file_ent:
        _log("ok", active.get("id"), meta={"count": 0, "note": "file entity not cached"})
        return {"data": {"styles": []}, "meta": {"count": 0}}

    out = []
    for a in assets:
        if not isinstance(a, dict):
            continue
        if a.get("asset_type") != "style":
