def get_style(key, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0470000" if __import__("os").path.isdir("./environment_mix/0470000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = datetime.datetime.now(datetime.timezone.utc)

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _isoz(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _lat_ms():
        return int((datetime.datetime.now(datetime.timezone.utc) - _t0).total_seconds() * 1000)

    def _append_log(status, credential_id=None, error_code=None, error_message=None, meta=None):
        logs = _load("figma_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "frl_" + os.urandom(12).hex(),
                "endpoint": "get_style",
                "credential_id": credential_id,
                "status": status,
                "error_code": error_code,
                "error_message": error_message,
                "latency_ms": _lat_ms(),
                "timestamp": _isoz(_now()),
                "meta": meta or {},
            }
        )
        _save("figma_request_logs.json", logs)

    # Validate input
    if not isinstance(key, str) or not key.strip():
        _append_log("error", None, "VALIDATION_ERROR", "key must be a non-empty string.", meta={"field": "key"})
        return _err("VALIDATION_ERROR", "key must be a non-empty string.", field="key")
    key = key.strip()

    # Ambient auth
    accounts = _load("figma_accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    active_accounts = [
        a for a in accounts
        if isinstance(a, dict) and a.get("status") == "active" and a.get("token_ciphertext")
    ]
    if not active_accounts:
        _append_log("error", None, "UNAUTHORIZED", "No active Figma API token is configured.")
        return _err("UNAUTHORIZED", "No active Figma API token is configured.")

    def _token_usable(acct):
        if not isinstance(acct, dict):
            return False
        if acct.get("status") != "active" or not acct.get("token_ciphertext"):
            return False
        ve = acct.get("validation_error") or ""
        if "401" in ve or "token invalid" in ve.lower():
            return False
        return True

    credential = None
    for acct in active_accounts:
        if _token_usable(acct):
            credential = acct
            break
    if credential is None:
        _append_log("error", None, "UNAUTHORIZED", "No usable active Figma API token is configured.")
        return _err("UNAUTHORIZED", "No usable active Figma API token is configured.")

    assets = _load("figma_asset_catalog.json")
    if not isinstance(assets, list):
        assets = []

    matches = [
        a for a in assets
        if isinstance(a, dict) and a.get("asset_key") == key and a.get("asset_type") == "style"
    ]

    if not matches:
        nk = key.strip()
        matches = [
            a for a in assets
            if isinstance(a, dict)
            and isinstance(a.get("asset_key"), str)
            and a.get("asset_key").strip() == nk
            and a.get("asset_type") == "style"
        ]

    if not matches:
        _append_log("error", credential.get("id"), "NOT_FOUND", "Style not found.", meta={"key": key})
        return _err("NOT_FOUND", "Style not found.", key=key)

    def _rank(row):
        status = row.get("status")
        st = 0 if status == "active" else 1 if status == "deprecated" else 2
        fetched = row.get("fetched_at")
        return (st, 0 if fetched else 1)

    matches.sort(key=_rank)
    asset = matches[0]

    out = {
        "style": asset.get("raw") if isinstance(asset.get("raw"), dict) else {
            "key": asset.get("asset_key"),
            "name": asset.get("name"),
            "description": asset.get("description"),
            "node_id": asset.get("node_id"),
        },
        "cache": {
            "id": asset.get("id"),
            "asset_type": asset.get("asset_type"),
            "status": asset.get("status"),
            "team_entity_id": asset.get("team_entity_id"),
            "file_entity_id": asset.get("file_entity_id"),
            "file_key": asset.get("file_key"),
            "fetched_at": asset.get("fetched_at"),
            "created_at": asset.get("created_at"),
            "updated_at": asset.get("updated_at"),
        },
    }

    _append_log("ok", credential.get("id"), None, None, meta={"key": key, "asset_id": asset.get("id")})
    return out

def get_me(include_quota=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0470000" if __import__("os").path.isdir("./environment_mix/0470000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    endpoint = "get_me"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, code=None, message=None, credential_id=None):
        logs = _load("figma_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "frl_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status,
            "error_code": code,
            "error_message": message,
            "credential_id": credential_id,
            "created_at": _now(),
            "latency_ms": int((time.time() - start) * 1000),
        })
        _save("figma_request_logs.json", logs)

    def _rate_limit_check():
        limits = _load("figma_rate_limits.json")
        if isinstance(limits, list) and limits:
            lim = limits[0] if isinstance(limits[0], dict) else None
        elif isinstance(limits, dict):
            lim = limits
        else:
            lim = None
        if not lim:
            return None
        rpm = lim.get("requests_per_minute")
        rpd = lim.get("requests_per_day")
        now = datetime.datetime.utcnow()
        logs = _load("figma_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        if isinstance(rpm, int) and rpm > 0:
            cutoff = now - datetime.timedelta(minutes=1)
            c = 0
            for r in logs:
                ts = r.get("created_at")
                if isinstance(ts, str) and ts.endswith("Z"):
                    try:
                        dt = datetime.datetime.fromisoformat(ts[:-1])
                    except Exception:
                        continue
                    if dt >= cutoff:
                        c += 1
            if c >= rpm:
                return _err("RATE_LIMIT", "Rate limit exceeded (requests_per_minute).")
        if isinstance(rpd, int) and rpd > 0:
            cutoff = now - datetime.timedelta(days=1)
            c = 0
            for r in logs:
                ts = r.get("created_at")
                if isinstance(ts, str) and ts.endswith("Z"):
                    try:
                        dt = datetime.datetime.fromisoformat(ts[:-1])
                    except Exception:
                        continue
                    if dt >= cutoff:
                        c += 1
            if c >= rpd:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded (requests_per_day).")
        return None

    try:
        if include_quota is not None and not isinstance(include_quota, bool):
            _log("error", "VALIDATION_ERROR", "include_quota must be a boolean when provided.")
            return _err("VALIDATION_ERROR", "include_quota must be a boolean when provided.")

        rl = _rate_limit_check()
        if rl:
            _log("error", rl["error"]["code"], rl["error"]["message"])
            return rl

        accounts = _load("figma_accounts.json")
        if not isinstance(accounts, list):
            accounts = []
        active = None
        for a in accounts:
            if isinstance(a, dict) and a.get("status") == "active" and a.get("token_ciphertext"):
                active = a
                break
        if not active:
            _log("error", "UNAUTHORIZED", "No active token configured.")
            return _err("UNAUTHORIZED", "No active token configured.")

        # Offline integration: infer identity from stored token metadata only.
        me = {
            "configured": True,
            "token": {
                "account_id": active.get("id"),
                "status": active.get("status"),
                "token_last4": active.get("token_last4"),
                "last_validated_at": active.get("last_validated_at"),
                "validation_error": active.get("validation_error"),
            },
            "user": active.get("me") if isinstance(active.get("me"), dict) else None,
            "scopes": active.get("scopes") if isinstance(active.get("scopes"), list) else [],
        }

        if include_quota:
            quota = {}
            limits = _load("figma_rate_limits.json")
            if isinstance(limits, list) and limits:
                lim = limits[0] if isinstance(limits[0], dict) else {}
            elif isinstance(limits, dict):
                lim = limits
            else:
                lim = {}
            quota["limits"] = lim if isinstance(lim, dict) else {}
            # Compute recent usage from request logs.
            logs = _load("figma_request_logs.json")
            if not isinstance(logs, list):
                logs = []
            now = datetime.datetime.utcnow()
            cutoff_1m = now - datetime.timedelta(minutes=1)
            cutoff_24h = now - datetime.timedelta(days=1)
            used_1m = 0
            used_24h = 0
            for r in logs:
                ts = r.get("created_at")
                if isinstance(ts, str) and ts.endswith("Z"):
                    try:
                        dt = datetime.datetime.fromisoformat(ts[:-1])
                    except Exception:
                        continue
                    if dt >= cutoff_1m:
                        used_1m += 1
                    if dt >= cutoff_24h:
                        used_24h += 1
            quota["observed_usage"] = {"requests_last_minute": used_1m, "requests_last_24h": used_24h}
            me["quota"] = quota

        _log("ok", credential_id=active.get("id"))
        return {"me": me}
    except Exception as e:
        _log("error", "CONFLICT", "Unexpected server error.")
        return _err("CONFLICT", "Unexpected server error.", detail=str(e))

