            return _err("VALIDATION_ERROR", "limit must be an integer in [1,1000].")
        start_index = _decode_cursor(cursor)
        if start_index is None:
            _log("error", "VALIDATION_ERROR", "Invalid cursor.")
            return _err("VALIDATION_ERROR", "Invalid cursor.")

        rl = _rate_limit_check()
