            _log("error", "UNAUTHORIZED", "No active token configured.")
            return _err("UNAUTHORIZED", "No active token configured.")

        # Only figma_entities are listed by this endpoint; refuse unsupported entity types beyond that schema.
        if entity_type is not None and entity_type not in {"team", "project", "file"}:
            _log("error", "VALIDATION_ERROR", "This integration cache only supports listing entity_type in {team, project, file}.")
            return _err("VALIDATION_ERROR", "Unsupported entity_type for list_entities in this cache.", supported=["team", "project", "file"])

        entities = _load("figma_entities.json")
        if not isinstance(entities, list):
            entities = []

        filtered = []
        for e in entities:
            if not isinstance(e, dict):
                continue
            if entity_type is not None and e.get("entity_type") != entity_type:
                continue
            if status is not None and e.get("status") != status:
                continue
            if parent_entity_id is not None and e.get("parent_entity_id") != parent_entity_id.strip():
                continue
            if figma_id is not None and e.get("figma_id") != figma_id.strip():
                continue
            if file_key is not None:
                # figma_entities has no file_key field; interpret this as matching file entities by figma_id.
                if e.get("entity_type") != "file" or e.get("figma_id") != file_key.strip():
                    continue
            if branch_data_included is not None:
                if e.get("branch_data_included") is not branch_data_included:
                    continue
            filtered.append(e)

        # Sort: most recently updated first (stable)
        def _k(x):
            return (x.get("updated_at") or "", x.get("created_at") or "", x.get("id") or "")
        filtered.sort(key=_k, reverse=True)

        total = len(filtered)
        page = filtered[start_index:start_index + limit]
        next_i = start_index + len(page)
        has_more = next_i < total
        next_cursor = _encode_cursor(next_i) if has_more else None

        _log("ok", credential_id=active.get("id"))
        return {
            "data": page,
            "meta": {
                "total": total,
                "limit": limit,
                "cursor": cursor,
                "has_more": has_more,
                "next_cursor": next_cursor,
            },
        }
    except Exception as e:
        _log("error", "CONFLICT", "Unexpected server error.")
        return _err("CONFLICT", "Unexpected server error.", detail=str(e))

def get_entity(id, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0470000" if __import__("os").path.isdir("./environment_mix/0470000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = datetime.datetime.now(datetime.timezone.utc)

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _isoz(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _lat_ms():
        return int((datetime.datetime.now(datetime.timezone.utc) - _t0).total_seconds() * 1000)

    def _append_log(status, credential_id=None, error_code=None, error_message=None, meta=None):
        logs = _load("figma_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "frl_" + os.urandom(12).hex(),
            "endpoint": "get_entity",
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": _lat_ms(),
            "timestamp": _isoz(_now()),
            "meta": meta or {}
        })
        _save("figma_request_logs.json", logs)

    # Validate
    if not isinstance(id, str) or not id.strip():
        _append_log("error", None, "VALIDATION_ERROR", "id must be a non-empty string.", meta={"field": "id"})
        return _err("VALIDATION_ERROR", "id must be a non-empty string.", field="id")
    id = id.strip()

    # Auth: do NOT refuse a well-formed request if there exists any usable active token
    accounts = _load("figma_accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    active = next((a for a in accounts if isinstance(a, dict) and a.get("status") == "active" and a.get("token_ciphertext")), None)
    if not active:
        _append_log("error", None, "UNAUTHORIZED", "No active Figma token is configured for this integration.")
        return _err("UNAUTHORIZED", "No active Figma token is configured for this integration.")

    entities = _load("figma_entities.json")
    if not isinstance(entities, list):
        entities = []

    row = next((e for e in entities if isinstance(e, dict) and e.get("id") == id), None)

    # Backwards-compat: some callers pass an account id; if so, return a synthetic NOT_FOUND? No: relax by looking in accounts too
    if row is None:
        acct_row = next((a for a in accounts if isinstance(a, dict) and a.get("id") == id), None)
        if acct_row is not None:
            # Return as a typed entity-like payload without fabricating new rows
            _append_log("ok", active.get("id"), meta={"resolved_from": "figma_accounts"})
            return {"data": {"id": acct_row.get("id"), "entity_type": "account", "raw": acct_row}}

        _append_log("error", active.get("id"), "NOT_FOUND", "Entity not found.", meta={"id": id})
        return _err("NOT_FOUND", "Entity not found.", id=id)

    _append_log("ok", active.get("id"))
    return {"data": row}

def update_entity(id, name=None, status=None, branch_data_included=None, list_cursor=None, list_page_size=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0470000" if __import__("os").path.isdir("./environment_mix/0470000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = datetime.datetime.now(datetime.timezone.utc)

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _isoz(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _lat_ms():
        return int((datetime.datetime.now(datetime.timezone.utc) - _t0).total_seconds() * 1000)

    def _append_log(status_s, credential_id=None, error_code=None, error_message=None, meta=None):
        logs = _load("figma_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "frl_" + os.urandom(12).hex(),
            "endpoint": "update_entity",
            "credential_id": credential_id,
            "status": status_s,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": _lat_ms(),
            "timestamp": _isoz(_now()),
            "meta": meta or {}
        })
        _save("figma_request_logs.json", logs)

    # Validate id
    if not isinstance(id, str) or not id.strip():
        _append_log("error", None, "VALIDATION_ERROR", "id must be a non-empty string.", meta={"field": "id"})
        return _err("VALIDATION_ERROR", "id must be a non-empty string.", field="id")
    id = id.strip()

    # Validate optional fields
    if name is not None and not isinstance(name, str):
        _append_log("error", None, "VALIDATION_ERROR", "name must be a string.", meta={"field": "name"})
        return _err("VALIDATION_ERROR", "name must be a string.", field="name")
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "archived", "deleted"):
            _append_log("error", None, "VALIDATION_ERROR", "status must be one of: active, archived, deleted.", meta={"field": "status"})
            return _err("VALIDATION_ERROR", "status must be one of: active, archived, deleted.", field="status")
    if branch_data_included is not None and not isinstance(branch_data_included, bool):
        _append_log("error", None, "VALIDATION_ERROR", "branch_data_included must be a boolean.", meta={"field": "branch_data_included"})
        return _err("VALIDATION_ERROR", "branch_data_included must be a boolean.", field="branch_data_included")
    if list_cursor is not None and not isinstance(list_cursor, str):
        _append_log("error", None, "VALIDATION_ERROR", "list_cursor must be a string.", meta={"field": "list_cursor"})
        return _err("VALIDATION_ERROR", "list_cursor must be a string.", field="list_cursor")
    if list_page_size is not None:
        if not isinstance(list_page_size, int) or list_page_size < 1 or list_page_size > 1000:
            _append_log("error", None, "VALIDATION_ERROR", "list_page_size must be an integer between 1 and 1000.", meta={"field": "list_page_size"})
            return _err("VALIDATION_ERROR", "list_page_size must be an integer between 1 and 1000.", field="list_page_size")

    # Auth (ambient)
    accounts = _load("figma_accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    active_acct = next((a for a in accounts if isinstance(a, dict) and a.get("status") == "active" and a.get("token_ciphertext")), None)
    if not active_acct:
        _append_log("error", None, "UNAUTHORIZED", "No active Figma token is configured for this integration.")
        return _err("UNAUTHORIZED", "No active Figma token is configured for this integration.")

    entities = _load("figma_entities.json")
    if not isinstance(entities, list):
        entities = []

    row = next((e for e in entities if isinstance(e, dict) and e.get("id") == id), None)

    # Backwards-compat: callers sometimes pass a figma_accounts id (observed in audit defects).
    # In that case, upsert a minimal entity row and then apply updates.
    now = _now()
    if row is None:
        acct_row = next((a for a in accounts if isinstance(a, dict) and a.get("id") == id), None)
        if acct_row is None:
            _append_log("error", active_acct.get("id"), "NOT_FOUND", "Entity not found.", meta={"id": id})
            return _err("NOT_FOUND", "Entity not found.", id=id)

        # Create an entity to allow update to succeed & persist.
        row = {
            "id": id,
            "entity_type": "file",          # default; unknown from account id; but must be a valid enum
            "figma_id": id,                 # store original identifier as vendor id placeholder
            "parent_entity_id": None,
            "name": None,
            "status": "active",
            "branch_data_included": None,
            "list_cursor": None,
            "list_page_size": None,
            "fetched_at": None,
            "raw": {"source": "backfill_from_account_id", "account": acct_row},
            "created_at": _isoz(now),
            "updated_at": _isoz(now),
        }
        entities.append(row)

    # Refuse updates to deleted entities (business rule)
    if row.get("status") == "deleted":
        _append_log("error", active_acct.get("id"), "INVALID_TRANSITION", "Refused: updates to deleted entities are not allowed.", meta={"id": id})
        return _err("INVALID_TRANSITION", "Refused: updates to deleted entities are not allowed.", id=id, current_status="deleted")

    # Lifecycle transitions
    if status is not None and status != row.get("status"):
        transitions = {
            "active": ["archived", "deleted"],
            "archived": ["active", "deleted"],
            "deleted": []
        }
        cur = row.get("status")
        if cur not in transitions:
            _append_log("error", active_acct.get("id"), "INVALID_TRANSITION", "Unknown current status; cannot transition.", meta={"current_status": cur})
            return _err("INVALID_TRANSITION", "Unknown current status; cannot transition.", current_status=cur)
        if status not in transitions[cur]:
            _append_log("error", active_acct.get("id"), "INVALID_TRANSITION", "Invalid lifecycle transition.", meta={"from": cur, "to": status})
            return _err("INVALID_TRANSITION", "Invalid lifecycle transition (rule: active↔archived, active/archived→deleted).", from_status=cur, to_status=status)
        row["status"] = status

    # Apply other field updates
    if name is not None:
        row["name"] = name
    if branch_data_included is not None:
        row["branch_data_included"] = branch_data_included
    if list_cursor is not None:
        row["list_cursor"] = list_cursor
    if list_page_size is not None:
        row["list_page_size"] = list_page_size

    row["updated_at"] = _isoz(now)

    _save("figma_entities.json", entities)
    _append_log("ok", active_acct.get("id"))
    return {"data": row}

def list_comments(fileKey, include_deleted=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0470000" if __import__("os").path.isdir("./environment_mix/0470000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list_comments"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential_id=None, error_code=None):
        logs = _load("figma_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now
        })
        _save("figma_request_logs.json", logs)

    def _active_account():
        accts = _load("figma_accounts.json")
        if not isinstance(accts, list):
            accts = []
        for a in accts:
            if isinstance(a, dict) and a.get("status") == "active" and a.get("token_ciphertext"):
                return a
        return None

    # Validate
    if not isinstance(fileKey, str) or not fileKey.strip():
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "fileKey must be a non-empty string", field="fileKey")

    if include_deleted is None:
        include_deleted = False
    if not isinstance(include_deleted, bool):
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "include_deleted must be a boolean", field="include_deleted")

    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 1000:
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 1000", field="limit")

    start = 0
    if cursor is not None:
        if not isinstance(cursor, str):
            _log("error", None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or obj.get("v") != 1 or not isinstance(obj.get("start"), int) or obj["start"] < 0:
                _log("error", None, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
            start = obj["start"]
        except Exception:
            _log("error", None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    acct = _active_account()
    if not acct:
        _log("error", None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active Figma token is configured for this integration.")

    comments = _load("figma_comments.json")
    if not isinstance(comments, list):
        comments = []

    rows = []
    for c in comments:
        if not isinstance(c, dict):
            continue
        if c.get("file_key") != fileKey:
            continue
        if not include_deleted and c.get("status") == "deleted":
            continue
        rows.append(c)

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            # tolerate Z
            if s.endswith("Z"):
                s2 = s[:-1]
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    rows.sort(key=lambda r: (_parse_dt(r.get("created_at")) or datetime.datetime.min), reverse=True)

    total = len(rows)
    page = rows[start:start + limit]
    next_start = start + len(page)
    has_more = next_start < total
    next_cursor = None
    if has_more:
        payload = json.dumps({"v": 1, "start": next_start}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    _log("ok", acct.get("id"))
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def revalidate_api_key(force=None, **_extra):
    import json, os, datetime, time, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0470000" if __import__("os").path.isdir("./environment_mix/0470000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "revalidate_api_key"
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _log(status, credential_id=None, error_code=None):
        logs = _load("figma_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now
        })
        _save("figma_request_logs.json", logs)

    # Validate force
    if force is None:
        force = False
    if not isinstance(force, bool):
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "force must be a boolean", field="force")

    accounts = _load("figma_accounts.json")
    if not isinstance(accounts, list):
        accounts = []

    # Find active token
    active_idx = None
    for i, a in enumerate(accounts):
        if isinstance(a, dict) and a.get("status") == "active" and a.get("token_ciphertext"):
            active_idx = i
            break
    if active_idx is None:
        _log("error", None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active Figma token is configured.")

    acct = accounts[active_idx]

    # Quota/rate limiting for upstream validation
    # Rule: max 60 validations per rolling 60 minutes across all accounts; else QUOTA_EXCEEDED.
    logs = _load("figma_request_logs.json")
    if not isinstance(logs, list):
        logs = []
    window_start = (now_dt - datetime.timedelta(minutes=60))
    validations = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("endpoint") != endpoint:
            continue
        ts = r.get("created_at")
        if not isinstance(ts, str):
            continue
        try:
            tss = ts[:-1] if ts.endswith("Z") else ts
            rdt = datetime.datetime.fromisoformat(tss)
        except Exception:
            continue
        if rdt >= window_start:
            validations += 1
    if validations >= 60:
        _log("error", acct.get("id"), "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Upstream validation quota exceeded. Try again later.")

    # If not forced and last validation is recent (5 minutes) and no validation_error and status active, reuse
    if not force:
        lva = acct.get("last_validated_at")
        if isinstance(lva, str):
            try:
                lvas = lva[:-1] if lva.endswith("Z") else lva
                ldt = datetime.datetime.fromisoformat(lvas)
                if (now_dt - ldt) <= datetime.timedelta(minutes=5) and acct.get("status") == "active" and not acct.get("validation_error"):
                    _log("ok", acct.get("id"))
                    return {"data": acct, "meta": {"cached": True}}
            except Exception:
                pass

    # Simulated upstream validation call (offline):
    # - If token_ciphertext missing => invalid
    # - If status not active => unauthorized
    # - Small chance of upstream rate limit => QUOTA_EXCEEDED
    if not acct.get("token_ciphertext"):
        acct["status"] = "invalid"
        acct["validation_error"] = "Token missing."
        acct["last_validated_at"] = now
        acct["updated_at"] = now
        accounts[active_idx] = acct
        _save("figma_accounts.json", accounts)
        _log("error", acct.get("id"), "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Token rejected by Figma.", validation_error=acct.get("validation_error"))

    # Upstream rate limit simulation
    if random.random() < 0.02:
        _log("error", acct.get("id"), "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Upstream validation rate-limited. Try again later.")

    # Consider token valid unless previously marked invalid/revoked; if invalid, allow transition invalid->active (per lifecycle)
    cur = acct.get("status")
    transitions = {"active": ("revoked", "invalid"), "invalid": ("active", "revoked"), "revoked": ()}

    # If revoked, cannot become active again; treat as unauthorized
    if cur == "revoked":
        acct["last_validated_at"] = now
        acct["validation_error"] = "Token is revoked and cannot be revalidated."
        acct["updated_at"] = now
        accounts[active_idx] = acct
        _save("figma_accounts.json", accounts)
        _log("error", acct.get("id"), "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Token rejected by Figma.", validation_error=acct.get("validation_error"))

    # Validate success: mark active and clear error
    if cur == "invalid":
        if "active" not in transitions.get("invalid", ()):
            _log("error", acct.get("id"), "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "Cannot transition token to active from invalid.")
        acct["status"] = "active"

    acct["last_validated_at"] = now
    acct["validation_error"] = None
    acct["updated_at"] = now
    accounts[active_idx] = acct
    _save("figma_accounts.json", accounts)

    _log("ok", acct.get("id"))
    return {"data": acct, "meta": {"cached": False}}
